CREATE TABLE public.bba_branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.bba_branches TO service_role;
ALTER TABLE public.bba_branches ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bba_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), login text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.bba_accounts TO service_role;
ALTER TABLE public.bba_accounts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bba_account_roles (account_id uuid PRIMARY KEY REFERENCES public.bba_accounts(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('super_admin','branch_admin')), branch_id uuid REFERENCES public.bba_branches(id), CHECK ((role='super_admin' AND branch_id IS NULL) OR (role='branch_admin' AND branch_id IS NOT NULL)));
CREATE UNIQUE INDEX bba_single_super_admin ON public.bba_account_roles (role) WHERE role='super_admin';
GRANT ALL ON public.bba_account_roles TO service_role;
ALTER TABLE public.bba_account_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bba_branch_state (branch_id uuid PRIMARY KEY REFERENCES public.bba_branches(id), data jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.bba_branch_state TO service_role;
ALTER TABLE public.bba_branch_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bba_branch_progress (branch_id uuid NOT NULL REFERENCES public.bba_branches(id), sid integer NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY(branch_id,sid));
GRANT ALL ON public.bba_branch_progress TO service_role;
ALTER TABLE public.bba_branch_progress ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.bba_create_admin(_login text, _hash text, _name text, _super boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid; bid uuid; BEGIN INSERT INTO public.bba_accounts(login,password_hash) VALUES (_login,_hash) RETURNING id INTO aid; IF _super THEN INSERT INTO public.bba_account_roles(account_id,role) VALUES (aid,'super_admin'); ELSE INSERT INTO public.bba_branches(name) VALUES (_name) RETURNING id INTO bid; INSERT INTO public.bba_account_roles(account_id,role,branch_id) VALUES (aid,'branch_admin',bid); INSERT INTO public.bba_branch_state(branch_id,data) VALUES (bid,'{"st":[],"qs":[],"res":[],"vars":[],"dur":90}'::jsonb); END IF; RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.bba_create_admin(text,text,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.bba_create_admin(text,text,text,boolean) TO service_role;